import{_ as s,c as t,o as i,a5 as n}from"./chunks/framework.BmNIwhaK.js";const u=JSON.parse('{"title":"5 Core Principles for Effective Issue Management","description":"Learn the core principles for using Jira effectively. Discover how assignment rules, commenting guidelines, and status management best practices improve project transparency and team productivity.","frontmatter":{"title":"5 Core Principles for Effective Issue Management","description":"Learn the core principles for using Jira effectively. Discover how assignment rules, commenting guidelines, and status management best practices improve project transparency and team productivity.","head":[["meta",{"name":"keywords","content":"Jira, issue management, Jira usage, project management, collaboration tool, assignment principles, commenting, status management, workflow, productivity improvement"}],["meta",{"property":"og:title","content":"5 Core Principles for Effective Issue Management | Empasy Docs"}],["meta",{"property":"og:description","content":"Learn the core principles for using Jira effectively. Discover how assignment rules, commenting guidelines, and status management best practices improve project transparency and team productivity."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage"}],["meta",{"name":"robots","content":"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/PrinciplesForIssueUsage"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"5 Core Principles for Effective Issue Management | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Learn the core principles for using Jira effectively. Discover how assignment rules, commenting guidelines, and status management best practices improve project transparency and team productivity."}],["script",{"type":"application/ld+json","data-empasy-page-jsonld":"true"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"5 Core Principles for Effective Issue Management\\",\\"description\\":\\"Learn the core principles for using Jira effectively. Discover how assignment rules, commenting guidelines, and status management best practices improve project transparency and team productivity.\\",\\"url\\":\\"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage\\",\\"inLanguage\\":\\"en-US\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://doc.empasy.com/images/favicon.png\\"}}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Empasy Docs (EN)\\",\\"item\\":\\"https://doc.empasy.com/en/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"5 Core Principles for Effective Issue Management\\",\\"item\\":\\"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage\\"}]}]}"]],"sort":6000},"headers":[],"relativePath":"en/agile/PrinciplesForIssueUsage.md","filePath":"en/agile/PrinciplesForIssueUsage.md","lastUpdated":1795293539000}'),a={name:"en/agile/PrinciplesForIssueUsage.md"};function r(o,e,l,c,p,m){return i(),t("div",null,[...e[0]||(e[0]=[n('<h2 id="core-principles-for-effective-issue-usage" tabindex="-1">Core Principles for Effective Issue Usage <a class="header-anchor" href="#core-principles-for-effective-issue-usage" aria-label="Permalink to “Core Principles for Effective Issue Usage”">​</a></h2><h3 id="_1-assignment-principles" tabindex="-1">1. <strong>Assignment Principles</strong> <a class="header-anchor" href="#_1-assignment-principles" aria-label="Permalink to “1. Assignment Principles”">​</a></h3><ul><li><strong>Assign to the current owner</strong>: An issue must always be assigned to the person currently performing the actual work.</li><li><strong>Acknowledge assignments promptly</strong>: Once an issue is assigned, the assignee should immediately acknowledge it and indicate whether work has started.</li><li><strong>No unassigned issues</strong>: Issues without an assigned owner are easily overlooked and neglected.</li></ul><h3 id="_2-commenting-principles" tabindex="-1">2. <strong>Commenting Principles</strong> <a class="header-anchor" href="#_2-commenting-principles" aria-label="Permalink to “2. Commenting Principles”">​</a></h3><ul><li><strong>Comment upon completion</strong>: Always add a comment summarizing the resolution when work is completed.</li><li><strong>Share progress updates</strong>: Post interim progress comments along the way, especially for long-running tasks.</li><li><strong>Comment on status transitions</strong>: When changing an issue&#39;s status (e.g., In Progress → Done), explicitly state the reason for the transition.</li><li><strong>Avoid meaningless comments</strong>: Do not repeatedly post low-value remarks such as &quot;Acknowledged&quot; or &quot;Working on it.&quot;</li></ul><h3 id="_3-status-management-principles" tabindex="-1">3. <strong>Status Management Principles</strong> <a class="header-anchor" href="#_3-status-management-principles" aria-label="Permalink to “3. Status Management Principles”">​</a></h3><ul><li><strong>Update status in real time</strong>: Update the issue status immediately to reflect current progress.</li><li><strong>Define statuses clearly</strong>: Establish clear, team-wide definitions for each status and apply them consistently.</li><li><strong>No stale statuses</strong>: Do not leave issues sitting in &quot;In Progress&quot; for extended periods without activity.</li></ul><h3 id="_4-issue-authoring-principles" tabindex="-1">4. <strong>Issue Authoring Principles</strong> <a class="header-anchor" href="#_4-issue-authoring-principles" aria-label="Permalink to “4. Issue Authoring Principles”">​</a></h3><ul><li><strong>Clear titles</strong>: Write titles that convey what needs to be done at a glance.</li><li><strong>Detailed descriptions</strong>: Include comprehensive details such as reproduction steps, expected results, and actual results.</li><li><strong>Complete required fields</strong>: Always fill in mandatory fields such as priority, time estimate, and component.</li><li><strong>Avoid vague language</strong>: Do not use ambiguous phrases like &quot;There&#39;s a bug&quot; or &quot;Please fix this.&quot;</li></ul><h3 id="_5-workflow-compliance-principles" tabindex="-1">5. <strong>Workflow Compliance Principles</strong> <a class="header-anchor" href="#_5-workflow-compliance-principles" aria-label="Permalink to “5. Workflow Compliance Principles”">​</a></h3><ul><li><strong>Follow the defined workflow</strong>: Strictly adhere to the workflow established by the team.</li><li><strong>Follow the review process</strong>: Never skip required steps such as code reviews or QA verification.</li><li><strong>Maintain process consistency</strong>: Ensure every team member follows the same process.</li></ul><h2 id="example-ideal-issue-processing-flow" tabindex="-1">Example: Ideal Issue Processing Flow <a class="header-anchor" href="#example-ideal-issue-processing-flow" aria-label="Permalink to “Example: Ideal Issue Processing Flow”">​</a></h2><ol><li><strong>Issue Created</strong> → Assign an owner + set priority</li><li><strong>Work Started</strong> → Change status to &quot;In Progress&quot; + post start comment</li><li><strong>In Progress</strong> → Post interim progress comments (as needed)</li><li><strong>Work Completed</strong> → Change status to &quot;Done&quot; + <strong>post a detailed resolution comment</strong></li><li><strong>Review Required</strong> → Change status to &quot;In Review&quot; + assign a reviewer</li></ol>',13)])])}const d=s(a,[["render",r]]);export{u as __pageData,d as default};
